import type { SierraAPI, SierraAPIConfig } from "./embed-types";
import "./embed-loader-modules";

/**
 * Global sierra object available when the embed script is loaded
 */
declare global {
    const sierra: SierraAPI;
    const sierraConfig: SierraAPIConfig | undefined;
}

export type {
    SierraAPI,
    SierraAPIConfig,
    SierraWebConfig,
    MessageAttachment,
    AttachmentHandler,
    AttachmentHandlerOpts,
    WebAttachmentDeclaration,
} from "./embed-types";

// Export OpenAI attachment types with prefixes to avoid naming conflicts
export type {
    UnknownObject as OpenAIAttachmentsUnknownObject,
    OpenAiGlobals as OpenAIAttachmentsGlobals,
    API as OpenAIAttachmentsAPI,
    CallTool as OpenAIAttachmentsCallTool,
    DisplayMode as OpenAIAttachmentsDisplayMode,
    Theme as OpenAIAttachmentsTheme,
    SafeAreaInsets as OpenAIAttachmentsSafeAreaInsets,
    SafeArea as OpenAIAttachmentsSafeArea,
    DeviceType as OpenAIAttachmentsDeviceType,
    UserAgent as OpenAIAttachmentsUserAgent,
    OpenAIToolOutput as OpenAIAttachmentsToolOutput,
    SET_GLOBALS_EVENT_TYPE as OpenAIAttachmentsSetGlobalsEventType,
    SetGlobalsEvent as OpenAIAttachmentsSetGlobalsEvent,
} from "./openai-types";
